
from __future__ import annotations

import re
from dataclasses import dataclass
from datetime import datetime, timedelta, timezone
from pathlib import Path

from sqlalchemy.orm import Session

from app.models.session_plan_attachment import SessionPlanAttachment
from app.services.session_plan.attachment_storage import (
    SessionPlanAttachmentStorage,
)


# Matches only keys generated by secrets.token_urlsafe(32)
# followed by an approved attachment extension.
_STORAGE_KEY_PATTERN = re.compile(
    r"^[A-Za-z0-9_-]{43}\.(pdf|doc|docx|ppt|pptx|jpg|jpeg|png)$"
)

DEFAULT_GRACE_PERIOD = timedelta(hours=24)


@dataclass(frozen=True)
class OrphanAttachmentCandidate:
    storage_key: str
    file_size_bytes: int
    modified_at: datetime


@dataclass(frozen=True)
class AttachmentReconciliationReport:
    scanned_files: int
    referenced_files: int
    orphan_candidates: tuple[OrphanAttachmentCandidate, ...]
    missing_files: tuple[str, ...]
    ignored_files: int


def build_attachment_reconciliation_report(
    db: Session,
    *,
    storage: SessionPlanAttachmentStorage | None = None,
    grace_period: timedelta = DEFAULT_GRACE_PERIOD,
    now: datetime | None = None,
) -> AttachmentReconciliationReport:
    """
    Build a read-only report of attachment storage consistency.

    No database records or physical files are modified.
    """

    if grace_period < timedelta(0):
        raise ValueError("Grace period cannot be negative.")

    storage = storage or SessionPlanAttachmentStorage()
    current_time = now or datetime.now(timezone.utc)

    if current_time.tzinfo is None:
        raise ValueError("The current time must be timezone-aware.")

    cutoff = current_time - grace_period

    referenced_keys = {
        row[0]
        for row in db.query(SessionPlanAttachment.storage_key).all()
    }

    existing_keys: set[str] = set()
    orphan_candidates: list[OrphanAttachmentCandidate] = []
    ignored_files = 0
    scanned_files = 0

    if not storage.root.is_dir():
        raise FileNotFoundError(
            f"Attachment storage directory does not exist: {storage.root}"
        )

    for entry in storage.root.iterdir():
        # Never follow symlinks or inspect directories.
        if entry.is_symlink() or not entry.is_file():
            ignored_files += 1
            continue

        if not _STORAGE_KEY_PATTERN.fullmatch(entry.name):
            ignored_files += 1
            continue

        scanned_files += 1
        existing_keys.add(entry.name)

        stat = entry.stat()
        modified_at = datetime.fromtimestamp(
            stat.st_mtime,
            tz=timezone.utc,
        )

        if entry.name in referenced_keys:
            continue

        if modified_at > cutoff:
            ignored_files += 1
            continue

        orphan_candidates.append(
            OrphanAttachmentCandidate(
                storage_key=entry.name,
                file_size_bytes=stat.st_size,
                modified_at=modified_at,
            )
        )

    missing_files = tuple(
        sorted(referenced_keys - existing_keys)
    )

    return AttachmentReconciliationReport(
        scanned_files=scanned_files,
        referenced_files=len(referenced_keys),
        orphan_candidates=tuple(
            sorted(
                orphan_candidates,
                key=lambda candidate: candidate.storage_key,
            )
        ),
        missing_files=missing_files,
        ignored_files=ignored_files,
    )
